n.exploreUrl:
@js:
   let result = [];
   let push = (title, url, size) => result.push({
       "title": title,
       "url": url,
       "style": {
        "layout_flexGrow": 1,
        "layout_flexBasisPercent": size
       }
});
   let bu = "https://www.zhwuxia.com/all/chuantongwuxia";              
   let a = org.jsoup.Jsoup.parse(java.ajax(bu)).select(".all-works-catalog ul li a");
   for (i in a) {
        let url = String(a[i].attr("href"))+"<,/page/{{page}}>"
        push(a[i].text(), url, 0.25);
    }
JSON.stringify(result);
